findings.codeql_raw_query:
/**
 * @name Environment variable injection
 * @description Setting environment variables from untrusted input without validation
 * @kind path-problem
 * @problem.severity warning
 * @id py/env-injection-dotenv
 * @tags security
 *        external/cwe/cwe-454
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module EnvInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember(["__setitem__", "update"]).getACall() and
      sink = call.getArg(_)
    )
  }
}

module EnvInjectionFlow = TaintTracking::Global<EnvInjectionConfig>;
import EnvInjectionFlow::PathGraph

from EnvInjectionFlow::PathNode source, EnvInjectionFlow::PathNode sink
where EnvInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Environment variable set from $@.", source.getNode(), "untrusted input"
